mapper.select:
SELECT /* QueryID : com.demo.proworks.stg.selectListPjt */ PJT_ID as pjtId, PJT_NAME as pjtName, PJT_ASI as pjtAsi, PJT_STATUS as pjtStatus, PJT_DETAIL as pjtDetail, CREATED_AT as createdAt, UPDATED_AT as updatedAt, PJT_ST as pjtSt, PJT_ET as pjtEt FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT * FROM PJT WHERE 1=1
AND PJT_ID like '%${scPjtId}%'
AND PJT_NAME like '%${scPjtName}%'
AND PJT_ASI like '%${scPjtAsi}%'
AND PJT_STATUS like '%${scPjtStatus}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}
